[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
# --room と日付を一緒に渡す（Issue #88）
u=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t13:00\t14:00\tz\nkaede\t2026-01-02\t09:00\t10:00\ty\n' > "$u"
[ "$(BOOKINGS=$u bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with date"; fail=1; }
# 値の無い --room は使い方の誤り（exit 2、usage を stderr に）
e=$(mktemp)
out=$(BOOKINGS=$t bash src/list.sh --room 2>"$e"); code=$?
[ $code = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without a value"; fail=1; }
# 形式の違う日付は --room の後ろでも exit 2
out=$(BOOKINGS=$t bash src/list.sh --room aoi 2026-1-01 2>"$e"); code=$?
[ $code = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'bad date: 2026-1-01 (expected YYYY-MM-DD)' ] || { echo "list --room with a malformed date"; fail=1; }
rm -f "$t" "$u" "$e"; exit $fail

